20	int cmd_list(const Cli& cli);
21	int cmd_doctor(const Cli& cli);
22	int cmd_build(const Cli& cli);
23	int cmd_run(const Cli& cli);
24	int cmd_state_diff(const Cli& cli);
25	}  // namespace andes_sim
