142	int main(int argc, char** argv) {
143	  using namespace andes_sim;
144	
145	  Cli cli = parse_cli(argc, argv);
146	  if (!cli.error.empty()) {
147	    std::fprintf(stderr, "andes-sim: %s\n", cli.error.c_str());
148	    return 2;
149	  }
150	
151	  if (cli.subcommand.empty()) {  // no command, or top-level -h
152	    if (cli.help) {
153	      print_usage(stdout);
154	      return 0;
155	    }
156	    print_usage(stderr);
157	    return 2;
158	  }
159	
160	  const Subcommand* sc = find(cli.subcommand);
161	  if (!sc) {
162	    std::fprintf(stderr, "andes-sim: unknown command '%s'\n\n",
163	                 cli.subcommand.c_str());
164	    print_usage(stderr);
165	    return 2;
166	  }
167	
168	  if (cli.help) {
169	    print_subcommand_help(*sc, stdout);
170	    return 0;
171	  }
172	
173	  if (cli.subcommand == "list") return cmd_list(cli);
174	  if (cli.subcommand == "doctor") return cmd_doctor(cli);
175	  if (cli.subcommand == "build") return cmd_build(cli);
176	  if (cli.subcommand == "run") return cmd_run(cli);
177	  if (cli.subcommand == "state-diff") return cmd_state_diff(cli);
178	
179	  // Remaining subcommands stub out until their feature lands. Resolve the repo
180	  // root so the discovery path stays live and observable.
181	  std::string root;
182	  try {
183	    root = repo_root().string();
184	  } catch (const std::exception& e) {
185	    root = std::string("<unknown: ") + e.what() + ">";
186	  }
187	  std::fprintf(stderr, "andes-sim %s: not yet implemented (repo root: %s)\n",
188	               cli.subcommand.c_str(), root.c_str());
189	  return 3;
190	}
