144	int list_engines() {
145	  Discovery disc = discover_engines();
146	
147	  // Columns describe engine identity only. Triggers are a hybrid-MODEL option
148	  // (see `list models` / `run --help`), not an engine attribute, so no TRIGGERS
149	  // column here.
150	  size_t we = 6, wt = 4, wk = 4;  // ENGINE, TYPE, KIND headers
151	  for (const EngineDescriptor& e : disc.engines) {
152	    we = std::max(we, e.id.size());
153	    wt = std::max(wt, e.type.size());
154	    wk = std::max(wk, e.kind.size());
155	  }
156	
157	  // Hardware params from each engine's --describe; "-" = not reported.
158	  std::printf("%s  %s  %s  XLEN  VLEN  DLEN  ELEN\n",
159	              ljust("ENGINE", we).c_str(), ljust("TYPE", wt).c_str(),
160	              ljust("KIND", wk).c_str());
161	  for (const EngineDescriptor& e : disc.engines)
162	    std::printf("%s  %s  %s  %-4s  %-4s  %-4s  %-4s\n", ljust(e.id, we).c_str(),
163	                ljust(e.type, wt).c_str(), ljust(e.kind, wk).c_str(),
164	                vlen_str(e.xlen).c_str(), vlen_str(e.vlen).c_str(),
165	                vlen_str(e.dlen).c_str(), vlen_str(e.elen).c_str());
166	
167	  // Binaries that could not self-describe are reported, never silently dropped.
168	  for (const std::string& w : disc.warnings)
169	    std::fprintf(stderr, "andes-sim: skipped engine: %s\n", w.c_str());
170	  return 0;
171	}
