175	int cmd_list(const Cli& cli) {
176	  // `fixtures` lists internal test ELFs -- a developer target, gated behind
177	  // ANDES_SIM_DEV so the release product offers only user-facing models/engines.
178	  const char* targets = is_dev_mode() ? "fixtures|models|engines" : "models|engines";
179	  if (cli.positional.empty()) {
180	    std::fprintf(stderr, "andes-sim list: expected one of %s\n", targets);
181	    return 2;
182	  }
183	  const std::string& t = cli.positional[0];
184	  if (t == "fixtures" && is_dev_mode()) return list_fixtures();
185	  if (t == "models") return list_models();
186	  if (t == "engines") return list_engines();
187	  std::fprintf(stderr, "andes-sim list: unknown target '%s' (want %s)\n",
188	               t.c_str(), targets);
189	  return 2;
190	}
