154	Discovery discover_engines() {
155	  Discovery out;
156	  std::set<std::string> seen;
157	
158	  EngineDescriptor qemu = builtin_qemu();
159	  seen.insert(qemu.id);
160	  out.engines.push_back(std::move(qemu));
161	
162	  if (const char* env = std::getenv("ANDES_SIM_ENGINES_DIR"); env && *env) {
163	    std::stringstream ss(env);
164	    std::string dir;
165	    while (std::getline(ss, dir, ':'))
166	      if (!dir.empty()) scan_dir(dir, /*prefix=*/"", out, seen);
167	  } else {
168	    scan_dir(repo_root() / "verilator" / "build", /*prefix=*/"sim_", out, seen);
169	  }
170	  return out;
