1	// Runtime engine discovery -- the hot-plug seam.
2	//
3	// discover_engines() returns the built-in qemu descriptor plus every engine
4	// found by scanning a directory and asking each binary to self-report via
5	// `--describe` (falling back to a <bin>.json sidecar). No engine is compiled
6	// into the framework; dropping a freshly built sim_<cfg> into the scan dir
7	// makes it appear here with no andes-sim rebuild.
8	//
9	// Scan dir: $ANDES_SIM_ENGINES_DIR (colon-separated; REPLACES the default and
10	// accepts any executable) if set, else <repo>/verilator/build (filtered to
11	// sim_* binaries).
12	#ifndef ANDES_SIM_ENGINE_REGISTRY_HPP
13	#define ANDES_SIM_ENGINE_REGISTRY_HPP
14	
15	#include <string>
16	#include <vector>
17	
18	#include "engine_descriptor.hpp"
19	#include "strutil.hpp"
20	
21	namespace andes_sim {
22	
23	struct Discovery {
24	  std::vector<EngineDescriptor> engines;   // deduped by id; qemu first
25	  std::vector<std::string> warnings;       // binaries that failed to describe
26	};
27	
28	Discovery discover_engines();
29	
30	// The bundled qemu descriptor (no directory scan, no --describe subprocess).
31	// discover_engines() seeds the registry with it; `run --model fast` resolves
32	// qemu through it directly, paying none of the Verilator-engine discovery cost.
33	EngineDescriptor builtin_qemu();
34	
35	// Rewrite a discovered engine's identity from the third-party simulator name to
36	// the product name: type "verilator" -> "vsim", id "verilator:<cfg>" ->
37	// "vsim:<cfg>". discover_engines() applies this once, before the id is used for
38	// dedup or shown anywhere, so every downstream consumer (list / --engine /
39	// errors / run banner) speaks "vsim" and a user never sees "verilator". Any
40	// other backend (qemu, a drop-in alioth/sid) passes through untouched.
41	inline void normalize_engine_label(EngineDescriptor& d) {
42	  if (d.type == "verilator") d.type = "vsim";
43	  if (d.id.rfind("verilator:", 0) == 0) d.id = "vsim:" + d.id.substr(10);
44	}
45	
46	// Select the cycle-accurate engine for `run --model cycle` from an
47	// already-discovered set (pure; spawns nothing). With `want_id` empty, default
48	// to the sole cycle-accurate engine -- erroring if there are none or more than
49	// one (ambiguous). With `want_id` set, that engine must exist and be
50	// cycle-accurate. Returns nullptr and sets `err` (naming the available
51	// cycle-accurate ids) on any failure; the returned pointer aliases into
52	// `engines`, so it must outlive the result.
53	inline const EngineDescriptor* resolve_accurate_engine(
54	    const std::vector<EngineDescriptor>& engines, const std::string& want_id,
55	    std::string& err) {
56	  auto is_accurate = [](const EngineDescriptor& e) {
57	    return e.kind == "cycle-accurate";
58	  };
59	  auto accurate_ids = [&] {
60	    std::vector<std::string> ids;
61	    for (const EngineDescriptor& e : engines)
62	      if (is_accurate(e)) ids.push_back(e.id);
63	    return join(ids, ", ");
64	  };
65	
66	  if (!want_id.empty()) {  // explicit --engine
67	    for (const EngineDescriptor& e : engines) {
68	      if (e.id != want_id) continue;
69	      if (is_accurate(e)) return &e;
70	      err = "engine '" + want_id + "' is " +
71	            (e.kind.empty() ? "not cycle-accurate" : e.kind) +
72	            "; model cycle needs a cycle-accurate engine";
73	      return nullptr;
74	    }
75	    std::string have = accurate_ids();
76	    err = "no engine '" + want_id + "'" +
77	          (have.empty() ? " (no cycle-accurate engines found)"
78	                        : " (cycle-accurate engines: " + have + ")");
79	    return nullptr;
80	  }
81	
82	  // No --engine: default to the sole cycle-accurate engine.
83	  const EngineDescriptor* sole = nullptr;
84	  int n = 0;
85	  for (const EngineDescriptor& e : engines)
86	    if (is_accurate(e)) { sole = &e; ++n; }
87	  if (n == 1) return sole;
88	  if (n == 0)
89	    err = "model cycle: no cycle-accurate engine found "
90	          "(build one with: andes-sim build --what vsim)";
91	  else
92	    err = "model cycle: multiple cycle-accurate engines; select one with "
93	          "--engine (have: " + accurate_ids() + ")";
94	  return nullptr;
95	}
96	
97	}  // namespace andes_sim
98	
99	#endif  // ANDES_SIM_ENGINE_REGISTRY_HPP
