1	// EngineDescriptor: the parsed result of an engine's `--describe` (or its
2	// sidecar <bin>.json). This struct IS the contract that QEMU, Verilator, and
3	// future engines (alioth, sid) speak to join the framework -- see
4	// docs/engine_interface.md. The framework keeps zero per-engine code; every
5	// capability it needs comes from here.
6	#ifndef ANDES_SIM_ENGINE_DESCRIPTOR_HPP
7	#define ANDES_SIM_ENGINE_DESCRIPTOR_HPP
8	
9	#include <string>
10	#include <string_view>
11	#include <vector>
12	
13	#include "json.hpp"
14	
15	namespace andes_sim {
16	
17	// One role's argv template, e.g. role "accurate-leg" -> {"{bin}",
18	// "--resume-from-qemu", "{state_in}", ...}. {placeholders} are filled by the
19	// plan executor (F6).
20	struct EngineInvoke {
21	  std::string role;
22	  std::vector<std::string> argv;
23	};
24	
25	struct EngineDescriptor {
26	  std::string id;                       // "qemu", "verilator:ax45mpv_premium"
27	  std::string type;                     // qemu | verilator | alioth | sid
28	  std::string kind;                     // functional | cycle-accurate
29	  long vlen = 0;                        // RVV params; 0 = not reported
30	  long dlen = 0;
31	  long elen = 0;
32	  long xlen = 0;
33	  std::vector<std::string> triggers;    // marker | pc | icount | simpoint
34	  std::vector<std::string> roles;       // standalone | fast-leg | accurate-leg
35	  std::vector<std::string> state;       // resume | drain (hybrid_state_v1 caps)
36	  std::vector<EngineInvoke> invoke;     // argv template per role
37	  std::string result;                   // stderr:<re> | state.mcycle
38	
39	  // Filled by the registry, not present in the JSON:
40	  std::string bin_path;                 // resolved path to the binary
41	  std::string source;                   // built-in | --describe | sidecar
42	
43	  const std::vector<std::string>* invoke_for(std::string_view role) const {
44	    for (const EngineInvoke& iv : invoke)
45	      if (iv.role == role) return &iv.argv;
46	    return nullptr;
47	  }
48	};
49	
50	// Build a descriptor from parsed JSON. Returns "" on success or an error
51	// message naming the first problem (id and type are required).
52	inline std::string descriptor_from_json(const json::Value& v,
53	                                        EngineDescriptor& out) {
54	  if (!v.is_object()) return "descriptor is not a JSON object";
55	
56	  const json::Value* id = v.find("id");
57	  if (!id || !id->is_string() || id->str.empty()) return "missing string 'id'";
58	  out.id = id->as_string();
59	
60	  const json::Value* type = v.find("type");
61	  if (!type || !type->is_string()) return "missing string 'type'";
62	  out.type = type->as_string();
63	
64	  if (const json::Value* x = v.find("kind")) out.kind = x->as_string();
65	  if (const json::Value* x = v.find("vlen")) out.vlen = x->as_int();
66	  if (const json::Value* x = v.find("dlen")) out.dlen = x->as_int();
67	  if (const json::Value* x = v.find("elen")) out.elen = x->as_int();
68	  if (const json::Value* x = v.find("xlen")) out.xlen = x->as_int();
69	  if (const json::Value* x = v.find("triggers")) out.triggers = x->as_string_array();
70	  if (const json::Value* x = v.find("roles")) out.roles = x->as_string_array();
71	  if (const json::Value* x = v.find("state")) out.state = x->as_string_array();
72	  if (const json::Value* x = v.find("result")) out.result = x->as_string();
73	
74	  if (const json::Value* inv = v.find("invoke"); inv && inv->is_object()) {
75	    for (size_t k = 0; k < inv->keys.size(); ++k)
76	      out.invoke.push_back({inv->keys[k], inv->vals[k].as_string_array()});
77	  }
78	  return "";
79	}
80	
81	}  // namespace andes_sim
82	
83	#endif  // ANDES_SIM_ENGINE_DESCRIPTOR_HPP
