77	// The standalone-passthrough spine shared by `fast` and `cycle`: both take a
78	// single ELF, then exec the resolved engine standalone with `extra` (model
79	// flags the framework forwards, e.g. fast's -m) followed by the post-`--`
80	// args verbatim (inherit stdio, no timeout, propagate exit code). The only
81	// per-model differences -- which engine, and how it is selected -- are resolved
82	// by the caller; `model` here only labels the positional diagnostics.
83	int run_standalone(const Cli& cli, const EngineDescriptor& eng,
84	                   const char* model,
85	                   const std::vector<std::string>& extra = {}) {
86	  if (int rc = check_one_elf(cli, model)) return rc;
87	  // QEMU's -bios flag searches its data directory for relative paths rather
88	  // than the CWD; resolve to absolute so both QEMU and vsim find the ELF.
89	  const std::string elf = abs_elf(cli.positional[0], "--model " + std::string(model));
90	  if (elf.empty()) return 2;
91	  std::vector<std::string> args = extra;
92	  args.insert(args.end(), cli.passthrough.begin(), cli.passthrough.end());
93	  std::string err;
94	  int rc = run_passthrough(eng, "standalone", elf, args, err);
95	  if (!err.empty()) std::fprintf(stderr, "andes-sim run: %s\n", err.c_str());
96	  return rc;
97	}
